{
  "tool": "noop",
  "description": "Log a transparency message when no significant actions are needed. Use this to confirm workflow completion and provide visibility when analysis is complete but no changes or outputs are required (e.g., 'No issues found', 'All checks passed'). This ensures the workflow produces human-visible output even when no other actions are taken.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "integrity": {
        "description": "Trustworthiness level of the message source (e.g., \"low\", \"medium\", \"high\").",
        "type": "string"
      },
      "message": {
        "description": "Status or completion message to log. Should explain what was analyzed and the outcome (e.g., 'Code review complete - no issues found', 'Analysis complete - all tests passing'). This is the only content field noop accepts; common aliases (reason, summary, details, text, note, status) are accepted and mapped to message. Serialize any metrics or structured run summary into this single string; other named fields (for example processed, skipped) are not accepted and cause a missing-message error.",
        "maxLength": 65536,
        "type": "string"
      },
      "secrecy": {
        "description": "Confidentiality level of the message content (e.g., \"public\", \"internal\", \"private\").",
        "type": "string"
      }
    },
    "required": [
      "message"
    ],
    "additionalProperties": false
  }
}
